css_extra:
.fluxo { flex-wrap:nowrap; align-items:stretch; margin:6px 0 }
.fluxo .et { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; padding:10px 12px; flex:1 1 0 }
.fluxo .et b { font-size:16.5px; line-height:1.25 }
.fluxo .et .et-sub { font-size:14.5px; line-height:1.3; color:var(--c) }
.fluxo .st { align-self:center; font-size:1.5em }
.fluxo .et-par { display:flex; flex-direction:column; gap:8px; flex:1 1 0 }
.fluxo .et-par .et { flex:1 1 auto }
.slbd.g .tb2.esq tr > *:nth-child(n+2) { text-align:left }
.slbd.g h3.tit-bloco { font-size:var(--fs-h3); color:var(--p) }
#s2 .tb2 tr > *:nth-child(2), #s5 .tb2 tr > *:nth-child(3), #s6 .tb2 tr > *:nth-child(2) { text-align:left }
#s2 .tb2 th:first-child { width:42% }
#s5 .tb2 th:first-child { width:13% } #s5 .tb2 th:nth-child(2) { width:18% }
#s5 .tb2 td { font-size:17.5px }
#s6 .tb2 th:first-child { width:40% }
#s3 .card.er { justify-content:space-between }
#s3 .card.er li { font-size:19px; margin:12px 0 }
#s3 .kpi span { font-size:15.5px }
#s4 .card, #s7 .card, #s8 .card.er { justify-content:center }
#s4 .card p, #s7 .card p { font-size:21px; line-height:1.55 }
#s4 .card h3, #s7 .card h3 { font-size:20px; margin-bottom:10px }
#s8 .card p { font-size:17.5px; line-height:1.5 }
#s8 .card.er p { font-size:19px }
#s9 .card li { font-size:20px; margin:14px 0 }
#s9 .card h3 { font-size:20px }
#s6 .card li { font-size:18px; margin:12px 0 }
